@@ -8,0 +8,6 @@ func Dispatch(tasks []Task) []chan error {
+	results := make([]chan error, len(tasks))
+	for i, t := range tasks {
+		results[i] = make(chan error)
+		go execute(t, results[i])
+	}
+	return results

