func TestReproUnbufferedDeadlock(t *testing.T) {
	results := Dispatch(make([]Task, 3))
	done := make(chan struct{})
	go func() { <-results[0]; close(done) }()
	select {
	case <-done:
	case <-time.After(200 * time.Millisecond):
		t.Log("DEADLOCK REPRODUCED: unbuffered send blocked")
	}
}
